Let $\alpha < H$, but sufficiently close to $H$.
		We recall the seminorm $\llbracket \,\cdot\, \rrbracket_{\mathcal{C}^{\alpha}_{[s, t]}}$ from \eqref{eq:holder_seminorm}.
		Since 

		\begin{align*}
			X_{s, t} = \int_s^t \sigma(X_r) \, \mathrm{d} B^H_r,
		\end{align*}

		the remainder estimate of Young integration, estimate \eqref{eq:young_fund_est}, gives 

		\begin{align}\label{eq:X_remainder_estimate}
			\abs{X_{s,t} - \sigma(X_s) B^H_{s, t}}
			\lesssim_{\alpha, \gamma} \norm{\sigma}_{\mathcal{C}^{\gamma}_x} \llbracket X \rrbracket_{\mathcal{C}^{\alpha}_{[s, t]}}^{\gamma} \left\|B^H\right\|_{\mathcal{C}^{\alpha}_{[s, t]}} 
			(t-s)^{(1 + \gamma) \alpha}.
		\end{align}


		By \cite[Lem.~10.7]{friz_victoir_2010}, we have
		\begin{align}\label{eq:young_sol_a_priori_bd}
			\llbracket X \rrbracket_{\mathcal{C}^{\alpha}_T}
			\lesssim_{\alpha, \gamma, T} (1 + \norm{\sigma}_{\mathcal{C}^{\gamma}_x} \norm{B^H}_{\mathcal{C}^{\alpha}_T})^{\frac{1}{\alpha}}. 
		\end{align}

		Now, due to Gaussianity of $B^H$ and as a consequence of the Kolmogorov continuity criterion, for all $p < \infty$, 
		there exists a $C\coloneqq C(p, \alpha, T, \norm{\sigma}_{\mathcal{C}_x^{\gamma}})>0$ such that

		\begin{align}\label{eq:X_holder_moment}
			\left\|\llbracket X \rrbracket_{\mathcal{C}_T^{\alpha}}\right\|_{L^p_{\omega}} \leq C.
		\end{align}

		Combining \eqref{eq:X_remainder_estimate} and \eqref{eq:X_holder_moment}, we get 

		$\norm{X_{s,t}}_{L^p_\omega} \lesssim (t-s)^H$.

		In particular, we have $\norm{\sigma(X)_{s, t}}_{L^p_\omega} \lesssim (t-s)^{\gamma H}$.
		To get an estimate of the remainder 
		$R_{s,t} = X_{s, t} - \sigma(X_s) B_{s, t}^H$,
		it suffices to apply the sewing lemma in $L^p_{\omega}$ with germ 
		$A_{s, t} \vcentcolon = \sigma(X_s) B_{s, t}^H$,

		since 

		\begin{equation*}
			\norm{\delta A_{s, u, t}}_{L^p_{\omega}} = \left\|\sigma(X)_{s, u} B^H_{u, t}\right\|_{L^p_{\omega}}
			\lesssim (t-s)^{(1 + \gamma) H}.          
		\end{equation*}

Let $\alpha \in (1/2,H)$ be arbitrarily close to $H$ and 
		$(X, B^H)$ and $(Y, B^H)$ be two weak solutions defined on the same filtered probability space $(\Omega,\mathcal{F},(\mathcal{F}_t),\mathbb{P})$  and driven by the same $(\mathcal{F}_t)$-fBm, $B^H$. 
		Since the requirement on $\gamma \in (\frac{1}{2H},1)$ is given by an open interval it is always possible to find a $\gamma' \in (\frac{1}{2H},\gamma)$. We then let $(\sigma_n)_{n=1}^{\infty}$ be a smooth approximation to $\sigma$ converging in $\mathcal{C}^{\gamma'}(\mathbb{R}^{d_1};\mathcal{M}(d_1,d_2))$ (which exists by the compact embedding between H\"older--Besov spaces).


		The remainder estimate of Young integration \eqref{eq:young_fund_est} gives 

		\begin{align}\label{eq:young_fundamental}
			\abs[\Big]{\int_s^t \sigma(Z_r) \, \mathrm{d} B^H_r - \sigma(Z_s) B^H_{s,t}}
			\lesssim_{\alpha, \gamma'} \norm{\sigma}_{\mathcal{C}_x^{\gamma'}} \norm{Z}_{\mathcal{C}_T^{\alpha}}^{\gamma'} 
			\left\|B^H\right\|_{\mathcal{C}^{\alpha}_T} (t-s)^{(1+\gamma') \alpha}
		\end{align}

		for $Z \in \{X, Y\}$.

		From the estimate \eqref{eq:young_fundamental} and convergence of the $\sigma_n$ in $\mathcal{C}^{\gamma'}(\mathbb{R}^{d_1};\mathcal{M}(d_1,d_2))$, it follows that

		\begin{align*}
			\lim_{n \to \infty} \int_0^{\cdot} \sigma_n(Z_r) \, \mathrm{d} B^H_r 
			= \int_0^{\cdot} \sigma(Z_r) \, \mathrm{d} B^H_r  
		\end{align*}

		uniformly in $[0, T]$. As the computation \eqref{eq:diff_linearisation} shows, 
		we have 

		\begin{align*}
			\int_0^t \left(\sigma_n(X_r) - \sigma_n(Y_r) \right) \, \mathrm{d} B^H_r 
			= \sum_k \int_0^t (X^{k}_r - Y^{k}_r) \, \mathrm{d} V^k_n(r),
		\end{align*}

		where 

		\begin{align*}
			V^k_n(r) \vcentcolon = 
			\int_0^1 \int_0^r \partial_k \sigma_n(\theta X_u + (1-\theta) Y_u) \, \mathrm{d} B^H_u \, \mathrm{d} \theta.
		\end{align*}

		Hence, we obtain 

		\begin{align}\label{eq:X_V_n}
			X_t - Y_t = \lim_{n \to \infty}
			\sum_k \int_0^t (X^{ k}_r - Y^{k}_r) \, \mathrm{d} V^k_n(r).
		\end{align}

		Now our task is to prove the convergence of $V_n$. 
		By Lem.~\ref{lem:sol_is_controlled}, for $(s,t) \in [0,T ]^2_{\leq}$ we have

		\begin{align*}
			\theta X_{s, t} + (1-\theta) Y_{s,t} 
			= (\theta \sigma(X_s) + (1-\theta) \sigma(Y_s)) B_{s, t} 
			+ R^{\theta}_{s, t}
		\end{align*}

		with 

		\begin{align*}
			\norm{R_{s, t}^{\theta}}_{L^p_{\omega}} \lesssim_{p, \gamma, x, \sigma} (t-s)^{(1 + \gamma) H}.                                     
		\end{align*}

		One technical problem is that 
		the Gubinelli derivative $\theta \sigma(X_s) + (1-\theta) \sigma(Y_s)$ might be degenerate, that is,  
		the matrix  

		\begin{align*}
			\left[\theta \sigma(X_s) + (1-\theta) \sigma(Y_s)\right] \left[\theta \sigma(X_s) + (1-\theta) \sigma(Y_s)\right]^{\top}
		\end{align*}

		could have an eigenvalue $0$. 
		(In the end, we will show that $X = Y$, hence it must be non-degenerate; but a priori we do not know this.)
		Because of this technical problem, we proceed as follows.

		{\bfseries Step 1.} We first assume that 

		\begin{align}\label{eq:sigma_low_oscillation}
			\sup_{x, \,y \in \mathbb{R}^d} \abs{\sigma(x) - \sigma(y)} \leq \frac{l^{-2}}{4},
		\end{align}

		where $l$ is the assumed ellipticity constant of $\sigma$. This condition implies that 
		for all $x,y\in \mathbb{R}^{d_1}$ and $\theta \in (0,1)$ we have

		\begin{align*}
			\left[\theta \sigma(x) + (1-\theta) \sigma(y)\right]& \left[\theta \sigma(x) + (1-\theta) \sigma(y)\right]^{\top}  \\
			&= [\sigma(x) + (1-\theta) (\sigma(y) - \sigma(x))] [\sigma(x) + (1-\theta) (\sigma(y) - \sigma(x))]^{\top} \\
			&\geq l^{-1} - \frac{l^{-1}}{2} - \frac{l^{-2}}{4} 
			\geq \frac{l^{-1}}{4}.
		\end{align*}

		Therefore, in combination of Lem.~\ref{lem:sol_is_controlled}, we see that

		\begin{align*}
			(\theta X + (1- \theta) Y, \theta \sigma(X) + (1-\theta) \sigma(Y)) \in \mathfrak{D}^{\gamma, l/4}_{B^H}.
		\end{align*}

		Prop.~\ref{prop:fbm_young} and standard embedding of H\"older--Besov spaces, yield

		\begin{equation*}
			\norm[\Big]{\int_s^t \partial_k (\sigma_n -\sigma_m)(\theta X_r^1 + (1-\theta) X_r^2) 
				\, \mathrm{d} B^H_r}_{L^p_{\omega}} \\
			\lesssim_{p, \gamma', x, \sigma} 
			\norm{\sigma_n -\sigma_m}_{\mathcal{C}_x^{\gamma'}} (t-s)^{\gamma' H}.
		\end{equation*}

		By Kolmogorov's continuity theorem, we see that 
		there exists a process $V^k$ such that for any $\beta < \gamma H$, 


		\begin{align*}
			\lim_{n \to \infty} \norm{\norm{V^k - V^k_n}_{\mathcal{C}^{\beta}_T}}_{L^p_{\omega}} = 0.
		\end{align*}

		Since $\gamma' H > 1/2$, we may take $\beta > 1/2$. Therefore, recalling \eqref{eq:X_V_n} we observe 

		\begin{align*}
			X_t - Y_t = \sum_k \int_0^t (X^{k}_r - Y^{k}_r) \, \mathrm{d} V^k_r \quad \text{a.s.}
		\end{align*}

		As this shows that $X - Y$ solves the linear Young differential equation 

		\begin{align*}
			\mathrm{d} x_t = \sum_k x^k_t \, \mathrm{d} V^k_t, \quad x_0 = 0,
		\end{align*}

		we see that $X - Y = 0$ a.s.

		{\bfseries Step 2.} Now we do not assume \eqref{eq:sigma_low_oscillation}. The new ingredient is a stopping time argument.
		We choose $\varepsilon > 0$ so that 

		\begin{align*}
			\sup_{x, y: \abs{x-y} \leq \varepsilon} \abs{\sigma(x) - \sigma(y)} \leq \frac{l^{-2}}{5},
		\end{align*}

		and we set $T^{(0)} \vcentcolon = 0$ and inductively


		\begin{align*}
			T^{(i)} \vcentcolon =\inf \set{t \geq T^{(i-1)} : \abs{X_t - X_{T^{(i-1)}}} \geq \varepsilon/2 \text{ or } \abs{Y_t - Y_{T^{(i-1)}}} \geq \varepsilon/2}.
		\end{align*}

		Using the notation $\llbracket X \rrbracket_{\mathcal{C}^{\alpha}_T}$ from \eqref{eq:holder_seminorm}, if $T^{(i)} \leq T$, 

		\begin{equation*}
			\frac{\varepsilon}{2} = \max\left\{\abs{X_{T^{(i)}} - X_{T^{(i-1)}}}, \abs{Y_{T^{(i)}} - Y_{T^{(i-1)}}}\right\} 
			\leq \max\left\{ \llbracket X \rrbracket_{\mathcal{C}_T^{\alpha}}, \llbracket Y \rrbracket_{\mathcal{C}_T^{\alpha}} \right\} 
			(T^{(i)} - T^{(i-1)})^{\alpha}.
		\end{equation*}

		Hence, the a priori estimate \eqref{eq:young_sol_a_priori_bd} implies that 


		\begin{align}\label{eq:T_i_unif_est}
			T^{(i)} - T^{(i-1)} \gtrsim_{\alpha, \gamma, T} \varepsilon^{-\frac{1}{\alpha}}  (1 + \norm{\sigma}_{\mathcal{C}^{\gamma}_x} \|B^H\|_{\mathcal{C}^{\alpha}_T})^{\frac{1}{\alpha^2}}			
		\end{align}

		uniformly over $i$, as long as $T^{(i)} \leq T$.

		To see that $X = Y$ a.s. up to time $T^{(1)}$, 
		let $\sigma^{(1)}$ be a $\gamma$-Hölder map such that $\sigma^{(1)} = \sigma$ in an $\varepsilon$-neighbourhood of 
		the initial condition $x$ and such that

		\begin{align*}
			\sup_{x, y \in \mathbb{R}^{d_1}} \abs{\sigma^{(1)}(x) - \sigma^{(1)}(y)} \leq \frac{l^{-2}}{4}.
		\end{align*}  
		We set 

		\begin{align*}
			X^{(1)}_t \vcentcolon = x + \int_0^t \sigma^{(1)}(X_r) \, \mathrm{d} r,
			\quad 
			Y^{(1)}_t \vcentcolon = x + \int_0^t \sigma^{(1)}(Y_r) \, \mathrm{d} r
		\end{align*}

		and 

		\begin{align*}
			V^{(1), k}_n(t) \vcentcolon = \int_0^t \int_0^1 \partial_k \sigma_n(\theta X^{(1)}_r + (1-\theta) Y^{(1)}_r) \, \mathrm{d} \theta \, \mathrm{d} B^H_r.
		\end{align*}

		Up to time $T^{(1)}$, we have 

		\begin{align*}
			X_t - Y_t = \lim_{n \to \infty}
			\sum_k \int_0^t (X^{ k}_r - Y^{k}_r) \, \mathrm{d} V^{(1), k}_n(r).
		\end{align*}

		Due to our choice of $\sigma^{(1)}$, the argument of Step 1 shows that $V^{(1), k}_n$ converges to some $V^{(1), k}$ 
		in $\mathcal{C}_T^{\beta}$, and that $X = Y$ up to time $T^{(1)}$.

		{\bfseries Step 3.}
		Obviously we want to repeat the operation of Step 2, but now there is a small problem that $X_{T^{(1)}}$ is random. 
		For this sake, let $(x_m)_{m \in \mathbb{N}}$ be a countable dense set of $\mathbb{R}^{d_1}$, and 
		let $\sigma^m$ be a $\gamma$-Hölder map such that 
		$\sigma^m = \sigma$ in an $\varepsilon$-neighbourhood of $x_m$ and such that 

		\begin{align}\label{eq:sigma_m_low_osc}
			\sup_{x, y \in \mathbb{R}^{d_1}} \abs{\sigma^m(x) - \sigma^m(y)} \leq \frac{l^{-2}}{4}.
		\end{align}  

		For each $m$ and $Z \in \{X, Y\}$, 
		we define the approximation,



		\begin{equation*}
			\Sigma^{Z, m}(t)  \vcentcolon = 
			\begin{cases}
				\sigma(Z_t) \mathbf{1}_{\{t \leq T^{(1)}\}} +\sigma^m(Z_t) \mathbf{1}_{\{t > T^{(1)}\}}, & \text{if } \abs{x_m - X_{T^{(1)}}} =  \abs{x_m - Y_{T^{(1)}}}\leq \varepsilon/2,\\
				\sigma(Z_{\min\{t, T^{(1)}\}}), & \text{otherwise },
			\end{cases}
		\end{equation*}

		along with the cut-off equations,

		\begin{align*}
			X^{(2, m)}_t \vcentcolon = x + \int_0^t \Sigma^{X, m}(r) \, \mathrm{d} B^H_r,\qquad Y^{(2, m)}_t \vcentcolon = x + \int_0^t \Sigma^{Y, m}(r) \, \mathrm{d} B^H_r

		\end{align*}

		and approximate linearisation,

		\begin{align*}
			V^{(2, m), k}_n (t) 
			\vcentcolon = \int_0^t \int_0^1 \partial_k \sigma_n(\theta X^{(2, m)}_r + (1-\theta) Y^{(2, m)}_r) \, \mathrm{d} \theta \, \mathrm{d} B^H_r.
		\end{align*}


		Notice that $X^{(2, m)}$, $Y^{(2, m)}$ are both adapted.
		We claim that, for $Z \in \{X, Y\}$, 

		\begin{align}\label{eq:Z_remainder_estimate}
			\abs{Z_{s, t}^{(2, m)} - \Sigma^{Z, m}(s) B^H_{s, t}} \lesssim 
			(\norm{\sigma}_{\mathcal{C}_x^{\gamma}} + \norm{\sigma^m}_{\mathcal{C}_x^{\gamma}}) 
			\norm{Z}_{\mathcal{C}_T^{\alpha}}^{\gamma} \left\| B^H \right\|_{\mathcal{C}_T^{\alpha}} (t-s)^{(1+ \gamma) \alpha}.
		\end{align}

		Indeed, by the remainder estimate of Young's integral \eqref{eq:young_fund_est}, 
		the estimate \eqref{eq:Z_remainder_estimate} is obvious if $t \leq T^{(1)}$ or if $s \geq T^{(1)}$. Suppose that $s < T^{(1)} < t$.
		If $\abs{x_m - X_{T^{(1)}}} \leq \varepsilon/2$, then 

		\begin{align*}
			\abs{Z_{s, T^{(1)}}^{(2, m)} - \sigma(Z_s) B^H_{s, T^{(1)}}} &\lesssim 
			\norm{\sigma}_{\mathcal{C}_x^{\gamma}} 
			\norm{Z}_{\mathcal{C}_T^{\alpha}}^{\gamma} \left\| B^H \right\|_{\mathcal{C}_T^{\alpha}} (t-s)^{(1+ \gamma) \alpha}, \\
			\abs{Z_{T^{(1)}, t}^{(2, m)} - \sigma^m(Z_{T^{(1)}}) B^H_{T^{(1)}, t}} &\lesssim 
			\norm{\sigma^m}_{\mathcal{C}_x^{\gamma}} 
			\norm{Z}_{\mathcal{C}_T^{\alpha}}^{\gamma} \left\| B^H \right\|_{\mathcal{C}_T^{\alpha}} (t-s)^{(1+ \gamma) \alpha}.
		\end{align*}

		Since $\abs{x_m - X_{T^{(1)}}} = \abs{x_m - Y_{T^{(1)}}} \leq \varepsilon/2$, we have 

		\begin{align*}
			\abs{\sigma^m(Z_{T^{(1)}}) - \sigma(Z_s)} = \abs{\sigma(Z_{T^{(1)}}) - \sigma(Z_s)} 
			\leq \norm{\sigma}_{\mathcal{C}_x^{\gamma}} \norm{Z}_{\mathcal{C}_T^{\alpha}}^{\gamma} (T^{(1)} - s)^{\gamma \alpha},
		\end{align*} 
		and the estimate \eqref{eq:Z_remainder_estimate} follows.
		The case where $\abs{x_m - X_{T^{(1)}}} > \varepsilon/2$ is similar.

		Now we check that the Gubinelli derivative $\Sigma^{\theta, m} \vcentcolon = \theta \Sigma^{X,m} + (1-\theta) \Sigma^{Y, m}$ is non-degenerate. Indeed, 
		for $t \leq T^{(1)}$ we have 

		\begin{align*}
			\Sigma^{\theta, m}(t) \Sigma^{\theta, m}(t)^{\top} = \sigma(X_t) \sigma(X_t)^{\top} \geq l^{-1},
		\end{align*}

		and for $t > T^{(1)}$ the condition \eqref{eq:sigma_m_low_osc} implies that 
		$\Sigma^{\theta, m}(t) \Sigma^{\theta, m}(t)^{\top} \geq l^{-1}/4$. 
		Therefore, Prop.~\ref{prop:fbm_young} and the Kolmogorov continuity theorem show that 
		$V^{(2, m)}_n$ converges to some $V^{(2, m)}$ in $L^p_{\omega}$. By the diagonalization argument, we may suppose that 
		almost surely for every $m \in \mathbb{N}$ and $\delta \in (0, \gamma H)$ we have 

		\begin{align*}
			\lim_{n \to \infty} \norm{V^{(2, m)} - V^{(2, m)}_n}_{\mathcal{C}_T^{\gamma H - \delta}} = 0.
		\end{align*}


		Since $(x_m)$ is dense, we can find a random $m = m(\omega)$ so that $\abs{x_m - X_{T^{(1)}}} < \varepsilon/2$. We then have 


		\begin{align*}
			X_t - Y_t = \sum_k \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} V^{(2, m), k}(r)
		\end{align*}

		up to $t \leq T^{(2)}$, hence $X = Y$ on $[0, T^{(2)}]$. 
		It is now clear that this algorithm can be continued, and at some point we must have $T^{(i)} \geq T$ due to \eqref{eq:T_i_unif_est}.

\label{def:rough_de_sol}
		Given $T>0$, $d_1,\,d_2 \in \mathbb{N}$, $H \in (1/3,1/2]$, $(B^H(\omega),\mathbb{B}^H(\omega))$ an almost sure realisation of the canonical, geometric rough path lift for the fBm with Hurst parameter $H$ (see Lem.~\ref{lem:canonical_lift}) and a map $\sigma :\mathbb{R}^{d_1}\to \mathcal{M}(d_1,d_2)$, we say that a path $(y,y')$ controlled by $(B^H(\omega),\, \mathbb{B}^H(\omega))$ is a \emph{solution to the rough differential equation}

		\begin{equation}\label{eq:rough_eq_pw}
			\mathrm{d} y_t = \sigma(y_t) \, \mathrm{d} B_t^H(\omega), \quad y_0 = x,
		\end{equation}

		on $[0,T]$, if the path $(\sigma(y),\nabla \sigma(y)y') \in \mathscr{D}^{\gamma \alpha}_{B^H(\omega)}$ for some $\alpha \in (1/3,H)$ and $\gamma >\frac{1-\alpha}{\alpha}$ and if for every $t\in [0,T]$ one has

		\begin{align*}
			y_t = x + \int_0^t \sigma(y_r) \, \mathrm{d} B_r^H(\omega),
		\end{align*}

		where the integral is understood as a rough integral as described in Sec.~\ref{sec:rough_integration}.

\label{def:weak_rough_sol}
		Given $T>0$, say that a tuple

		\begin{equation*}
			(\Omega,\mathcal{F},(\mathcal{F}_t)_{t\in [0,T]}, \mathbb{P},B^H,X,X'),
		\end{equation*}

		of a filtered probability space, an fBm of Hurst parameter $H$ and an $(\mathcal{F}_t)$-adapted, controlled rough path, $(X,X')$ is a weak-rough solution to \eqref{eq:main_sde_rough}, if $B^H$ is an $(\mathcal{F}_t)_{t\geq 0}$ fBm (in the sense of Def.~\ref{def:adapted_fBm}) and for $\mathbb{P}$-a.e $\omega \in \Omega$,  the process $(X(\omega),X'(\omega))$ is a rough solution to \eqref{eq:main_sde_rough}in the sense of Def.~\ref{def:rough_de_sol}.

		We say that weak uniqueness holds for \eqref{eq:main_sde_rough} in the rough sense, if for any two weak solutions $(\Omega,\mathcal{F},(\mathcal{F}_t)_{t\geq 0}, \mathbb{P},B^H,X,X')$ and $(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}_t})_{t\geq 0}, \tilde{\mathbb{P}},\tilde{B}^H,\tilde{X},\tilde{X}')$ as above, the processes $(X,X'),\, (\tilde{X},\tilde{X}')$ are equal in law, i.e. one has 

		\begin{equation*}
			(X,X')_{\#} \mathbb{P} = (\tilde{X},\tilde{X}')_{\#}\tilde{\mathbb{P}}  \quad \text{as elements of}\quad  \mathcal{P}\left(C([0,T];\mathbb{R}^{d_1})\times C\left([0,T];\mathcal{M}(d_1,d_2)\right)\right)
		\end{equation*}

\label{rem:weak_rough_existence_compactness}


		As mentioned in the Young case (Rem.~\ref{rem:weak_young_existence_compactness}) a standard compactness argument (a la \cite[Appendix~B]{matsuda22}) allows one to construct weak-rough solutions in the case $\sigma\in \mathcal{C}^{\gamma}(\mathbb{R}^{d_1};\mathcal{M}(d_1,d_2))$ for $\gamma>\frac{1-H}{H}$. Note that in contrast to Def.~\ref{def:rough_de_sol} this is explicitly an assumption on the coefficient $\sigma$ which in turn ensures the required regularity of the controlled path $(\sigma(X),\nabla \sigma(X),X')$ for some $\alpha \in (1/3,H)$ sufficiently close to $H$.

		In the regime $H\in (1/3,1/2)$ our main result (Thm.~\ref{thm:main}) obtains pathwise uniqueness for $\sigma$  that is $\gamma$-H\"older continuous for $\gamma >\frac{1-H}{H}$ and uniformly elliptic so that we obtain pathwise uniqueness for these weak solutions (under the assumption of uniform ellipticity) and hence strong existence due to Prop.~\ref{prop:yamada_watanabe}.

