\label{lem:linearization_rough}
		Let $\gamma \in ((1-H)/H, 2)$, $\alpha \in (1/3, H)$ be such that $\gamma + \gamma \alpha > 1$, $\rho \in C^\infty(\mathbb{R}^{d_1};\mathcal{M}(d_1,d_2))$,  $(X, X'), (Y, Y') \in \mathscr{D}^{\gamma \alpha}_{B^H}$


		and for $k=1, 2, \ldots, d_1$ let us set $\mathbf{G}^k[\rho] = (G^k[\rho], \mathcal{G}^k[\rho])$ as in \eqref{eq:G_k_def} and \eqref{eq:curl_G_k}. Then it holds that 

		\begin{align*}
			\int_0^t \left(\rho(X_r) - \rho(Y_r)\right) \, \mathrm{d} B_r^H 
			= \sum_{k=1}^{d_1} \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \mathbf{G}_r^k[\rho],
		\end{align*}


		where the integral with respect to $\mathbf{G}^k[\rho]$ is understood in the same sense as \eqref{eq:rough_int_along_G}.

The proof is completely pathwise.
		We set 

		\begin{align*}
			A^1_{s, t} &\vcentcolon = 
			\left( \rho(X_s) - \rho(Y_s) \right) B^H_{s, t}  
			+ \left(\nabla \rho(X_s) X_s' -\nabla \rho(Y_s) Y_s'\right) \mathbb{B}^H_{s, t},  \\
			A^2_{s, t} &\vcentcolon = \sum_{k=1}^{d_1} (X^k_s - Y^k_s) G_{s, t}^k + \left( (X'_s)^k - (Y'_s)^k \right) \mathcal{G}^k_{s, t},
		\end{align*}  

		where as usual $X^k$ denotes the $k^{\text{th}}$ element of $X \in \mathbb{R}^{d_1}$ and $(X')^k$ denotes the $k^{\text{th}}$ row of the matrix $X' \in \mathcal{M}(d_1,d_2)$, similarly for $Y,\,Y'$.


		In addition, the second term in $A^1_{s, t}$ should be understood as a $d_1$-dimensional vector whose $i^{\text{th}}$ component is given by 

		\begin{align*}
			\sum_{j, k, l}  \left(\partial_k\rho^{i j}(X_s) (X'_s)^{k l} - \partial_k\rho^{i j}(Y_s) (Y'_s)^{k l}\right) \mathbb{B}_{s, t}^{H, l j}.
		\end{align*}

		Note that 

		\begin{align*}
			\int_0^t \big(\,\rho(X_r) - \rho(Y_r)\big) \, \mathrm{d} B^H_r 
			&= \lim_{\substack{\pi \text{ is a partition of } [0, t], \\\abs{\pi} \to 0}} \sum_{[u, v] \in \pi} A^1_{u, v},  \\
			\sum_{k=1}^{d_1} \int_0^t \big(X^k_r - Y^k_r\big) \, \mathrm{d} \mathbf{G}_r^k[\rho]
			&= \lim_{\substack{\pi \text{ is a partition of } [0, t], \\\abs{\pi} \to 0}} \sum_{[u, v] \in \pi} A^2_{u, v}.
		\end{align*}

		Therefore, by the uniqueness part of the deterministic sewing lemma (Rem.~\ref{rem:sewing_uniq}), it suffices to show $\abs{A^1_{s, t} - A^2_{s, t}} \lesssim (t-s)^{3H}$. 
		It follows from the mean value theorem that we have both

		\begin{align}\label{eq:rho_mv}
			\rho(X_s) - \rho(Y_s) = \sum_{k=1}^{d_1} \int_0^1 \partial_k \rho(\theta X_s + (1-\theta) Y_s) (X^k_s - Y^k_s) \, \mathrm{d} \theta
		\end{align}

		and 

		\begin{multline}
			\label{eq:nabla_rho_mv}
			\nabla \rho(X_s) X_s' - \nabla \rho(Y_s) Y_s' 
			= \sum_{k=1}^{d_1} 
			\Big( \int_0^1 (X^k_s - Y^k_s) \partial_k \nabla \rho(\theta X_s + (1-\theta) Y_s) \\
			\times (\theta X_s' + (1-\theta) Y_s') \, \mathrm{d} \theta 
			+ \int_0^1 (X_s' - Y_s')^k \partial_k \rho(\theta X_s + (1-\theta) Y_s)  \, \mathrm{d} \theta \Big).
		\end{multline}

		By \eqref{eq:rho_mv} and \eqref{eq:nabla_rho_mv}, we compute 


		\begin{align*}
			A^2_{s, t} - A^1_{s, t} 
			= \sum_{k=1}^{d_1} \left( (X^k_s - Y^k_s) \Delta^{1, k}_{s, t} + 
			\left( (X'_s)^k - (Y'_s)^k \right) \Delta^{2, k}_{s, t} \right),
		\end{align*}

		where 

		\begin{align*}
			\Delta^{1, k}_{s, t} \vcentcolon = &\int_s^t \Big( \int_0^1 \partial_k \rho(\theta X_r + (1-\theta) Y_r) \, \mathrm{d} \theta \Big) \, \mathrm{d} B^H_r
			- \left(  \int_0^1 \partial_k \rho(\theta X_s + (1-\theta) Y_s) \, \mathrm{d} \theta \right) B^H_{s, t}  \\
			&- \Big(  \int_0^1 \partial_k \nabla \rho(\theta X_s + (1-\theta) Y_s) (\theta X_s' + (1-\theta) Y_s') \, \mathrm{d} \theta \Big) \mathbb{B}^H_{s, t}
		\end{align*}

		and 

		\begin{multline*}
			\Delta^{2, k}_{s, t} \vcentcolon = \int_s^t \Big(  \int_0^1 \partial_k \rho(\theta X_r + (1-\theta) Y_r) \, \mathrm{d} \theta \Big) B^H_{s,r} \otimes \, \mathrm{d} B^H_r \\
			- \Big(  \int_0^1 \partial_k \rho(\theta X_s + (1-\theta) Y_s) \, \mathrm{d} \theta \Big) \mathbb{B}^H_{s, t}.
		\end{multline*}

		By the remainder estimate of the rough integral \eqref{eq:rough_fund_est} and assumed regularity of $\rho$,  
		both $\Delta^{1, k}_{s, t}$ and $\Delta^{2, k}_{s, t}$ are bounded by $(t-s)^{3H}$ up to constant, 


		and the proof is complete.

We assume that \eqref{eq:sigma_low_oscillation} holds, as the general case is handled by stopping time arguments as exhibited in the proof of Thm.~\ref{thm:pathwise_uniqueness_young}.
		Let $(X, B^H)$ and $(Y, B^H)$ be two weak solutions to \eqref{eq:main_sde_rough} defined on the same filtered probability space $(\Omega,\mathcal{F},(\mathcal{F}_t)_{t\in [0,T]},\mathbb{P})$  and driven by the same $(\mathcal{F}_t)$-fBm, $B^H$. 
		Since the requirement on $\gamma \in ((1-H/H,2))$ is given by an open interval it is always possible to find a $\gamma' \in ((1-H)/H,\gamma)$. We then let $(\sigma_n)_{n=1}^{\infty}$ be a smooth approximation to $\sigma$ converging in $\mathcal{C}^{\gamma'}(\mathbb{R}^{d_1};\mathcal{M}(d_1,d_2))$ (which exists by the compact embedding between H\"older--Besov spaces).
		By \cite[Lem~7.2]{FH20} or \cite[Eq.~(1.8)]{dareiotisgerencser22}, 
		we have 

		\begin{equation*}
			\lim_{n \to \infty} \norm{((\sigma - \sigma_n)(X_r), \nabla (\sigma - \sigma_n)(X_r) X'_r)}_{\mathscr{D}^{\gamma \alpha}_{B^H}} = 0
		\end{equation*}

		and similarly for $Y$.
		In view of \eqref{eq:rough_fund_est}, we then have 


		\begin{align*}
			X_t - Y_t = \lim_{n \to \infty} \int_0^t \left(\sigma_n(X_r) - \sigma_n(Y_r)\right) \, \mathrm{d} B^H_r,
		\end{align*}

		and so by Lem.~\ref{lem:linearization_rough}, 

		\begin{align*}
			X_t - Y_t = \lim_{n \to \infty} \sum_{k=1}^{d_1} \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \mathbf{G}^k_r[\sigma_n].
		\end{align*}

		By repeating the argument of Lem.~\ref{lem:sol_is_controlled}, we can show that 
		$(X, \sigma(X)) \in \mathfrak{D}^{1, l}_{B^H}$ and similarly for $Y$.
		Furthermore, by the condition \eqref{eq:sigma_low_oscillation}, as checked in Step 1 of the proof of Thm.~\ref{thm:pathwise_uniqueness_young}, we have 

		\begin{align*}
			\theta X + (1-\theta) Y \in \mathfrak{D}^{1, l/4}_{B^H}, \quad \forall \theta \in [0, 1].
		\end{align*}

		Therefore, by Prop.~\ref{prop:fbm_rough} \& \ref{prop:rough_iterated_integral} (with $f = \partial_k \sigma_n - \partial_k \sigma_m$), 


		and the Kolmogorov criterion for rough paths 
		(\cite[Thm.~3.1]{FH20}), the sequence of the lifts $\mathbf{G}^k[\sigma_n]$ converges in $L^p(\Omega;\mathbb{R})$ to some limit 
		$\mathbf{G}^k[\sigma] = (G^k[\sigma], \mathcal{G}^k[\sigma])$ in the metric $d_{\alpha, \gamma'}$ defined by \eqref{eq:mod_rp_metric}. 
		Namely, for all  $k = 1, 2, \ldots, d_1$ and $p \in [1, \infty)$,

		\begin{equation*}
			\lim_{n \to \infty} \norm{d_{\alpha, \gamma'}(\mathbf{G}^k[\sigma_n], \mathbf{G}^k[\sigma])}_{L^p_\omega} = 0
		\end{equation*}

		The stability estimate \eqref{eq:modified_rp_stab} yields 

		\begin{align*}
			X_t - Y_t = \sum_{k=1}^{d_1} \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \mathbf{G}^k_r[\sigma] \quad \text{a.s.}
		\end{align*}


		The remainder estimate \eqref{eq:mod_rp_remainder} shows that $X-Y$ is controlled by $(G^k)_{k=1}^{d_1}$ with 
		Gubinelli derivative $X - Y$. 
		Moreover, similarly to $\mathbf{G}^k[\sigma]$, by Prop.~\ref{prop:rough_itr_int_2} (with $f = \partial_k \sigma_n - \partial_k \sigma_m$, $g = \partial_l \sigma_n$ and $f = \partial_k \sigma_n$, $g = \partial_l \sigma_n - \partial_l \sigma_m$) and the Kolmogorov criterion for rough paths, the sequence of the rough paths 

		\begin{align*}
			\hat{\mathbf{G}}[\sigma_n] \vcentcolon = \Big((G^k[\sigma_n])_{k=1}^{d_1}, \Big(\int G^k[\sigma_n] \otimes \, \mathrm{d} G^l[\sigma_n] \Big)_{k,l=1}^{d_1}\Big) 
		\end{align*}

		converges to some limit $\hat{\mathbf{G}}[\sigma]$.  
		We claim that 

		\begin{align}\label{eq:mod_rp_vs_rp}
			\int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \mathbf{G}^k_r[\sigma]
			= \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \hat{\mathbf{G}}^k_r[\sigma] \quad \text{a.s.}
		\end{align}

		We note that the integral in the right-hand side is defined as rough integral with respect to $\hat{\mathbf{G}}[\sigma]$, which is well-defined since 
		$X-Y$ is controlled by $(G^k)_{k=1}^{d_1}$ with Gubinelli derivative $X-Y$.
		To see \eqref{eq:mod_rp_vs_rp}, we again rely on the uniqueness part of the sewing lemma (Rem.~\ref{rem:sewing_uniq}). By definition we have

		\begin{align*}
			\int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \mathbf{G}^k_r
			- \int_0^t (X^k_r - Y^k_r) \, \mathrm{d} \hat{\mathbf{G}}^k_r
			= \lim_{\substack{\pi \text{ is a partition of } [0, t], \\ \abs{\pi} \to 0}} 
			\sum_{[u, v] \in \pi} \Delta_{u, v},
		\end{align*}

		where 


		\begin{align*}
			\Delta_{s, t} \vcentcolon = &\,(\sigma(X_s) - \sigma(Y_s)) \mathcal{G}^k_{s, t}[\sigma] 
			- \sum_{l=1}^{d_1} (X^l_s - Y^l_s) \int_s^t G^l_{s, r}[\sigma] \otimes \, \mathrm{d} G_r^k[\sigma] \\ 
			= &\sum_{l=1}^{d_1} (X^l_s - Y^l_s)  \left( \left( \int_0^1 \partial_l \sigma(\theta X_s + (1-\theta) Y_s) \, \mathrm{d} \theta \right) \mathcal{G}^k_{s, t}[\sigma]- \int_s^t G^l_{s, r}[\sigma] \otimes \, \mathrm{d} G_r^k[\sigma] \right).
		\end{align*}

		By Prop.~\ref{prop:rough_iterated_integral} \& \ref{prop:rough_itr_int_2}, 

		\begin{equation*}
			\norm[\Big]{\Big( \int_0^1 \partial_l \sigma(\theta X_s + (1-\theta) Y_s) \, \mathrm{d} \theta \Big) \mathcal{G}^k_{s, t} - \int_s^t G^l_{s, r} \otimes \, \mathrm{d} G_r^k\,}_{L^p_{\omega}} 
			\lesssim (t-s)^{(1+\gamma') H},
		\end{equation*}

		and as $(1+\gamma)H > 1$ the identity \eqref{eq:mod_rp_vs_rp} is established.

		Hence, $X-Y$ solves the linear rough differential equation 

		\begin{align*}
			\mathrm{d} Z_t = \sum_{k=1}^{d_1} Z_t^k \, \mathrm{d} \hat{\mathbf{G}}_t^k, \quad Z_0 = 0,  
		\end{align*}

		and its uniqueness implies that for $\mathbb{P}$-a.e. $\omega$ we have  $X(\omega) = Y(\omega)$, which concludes the proof.

\label{lem:semigroup_regularisation}
			Let $c \in (1, \infty)$ and $\Gamma \in \mathcal{M}_+$ such that $c^{-1} \leq \Gamma \leq c$. 

			Then,
			for $\alpha, \beta \in \mathbb{R}$ with $\beta \geq 0 \vee \alpha$ and $t \in (0, T)$ one has

			\begin{equation*}
				\norm{\mathcal{P}_{t\Gamma } f}_{\mathcal{C}^{\beta}_x} \lesssim_{c, \alpha, \beta} (t \wedge 1)^{-\frac{\beta-\alpha}{2}}
				\norm{f}_{\mathcal{C}^{\alpha}_x}.
			\end{equation*}

We write

			\begin{equation}\label{eq:Lambda}
				\Lambda_{\Gamma} f(x) \vcentcolon = f(\sqrt{\Gamma} x).
			\end{equation}

			Then $\mathcal{P}_{t\Gamma} f = \Lambda_{\Gamma^{-1}} \mathcal{P}_{t} \Lambda_{\Gamma} f$.
			Since

			\begin{equation*}
				\norm{\Lambda_{\Gamma}f }_{\mathcal{C}_x^{\gamma}} \lesssim_{c, \gamma} \norm{f}_{\mathcal{C}_x^{\gamma}}
				\lesssim_{c, \gamma} \norm{\Lambda_{\Gamma}f }_{\mathcal{C}_x^{\gamma}},
			\end{equation*}

			we can assume that $\Gamma = I_d$. Then the claim follows from \cite[Lem.~2.3]{dareiotis_gerenscer_le_23_euler}, note that the inclusion of $t=1$ in the definition of the inhomogeneous H\"older-Besov norm makes no difference to the arguments given therein..

\label{lem:semigroup_difference}
			Let $c \in (1, \infty)$ and let $\Gamma_i \in \mathcal{M}_+$ $(i = 1, 2)$ be such that $c^{-1} \leq \Gamma_i \leq c$. Then,
			for $\alpha, \beta \in \mathbb{R}$ with $\beta \geq \alpha \vee 0$ and $t \in (0, T)$ we have

			\begin{equation*}
				\norm{(\mathcal{P}_{t \Gamma_1} - \mathcal{P}_{t\Gamma_2 }) f}_{\mathcal{C}_x^{\beta}}
				\lesssim_{c, \alpha, \beta} (t \wedge 1)^{-\frac{\beta-\alpha}{2}} \abs{\Gamma_1 - \Gamma_2}
				\norm{f}_{\mathcal{C}_x^{\alpha}}.
			\end{equation*}

We first claim

			\begin{equation}\label{eq:semigroup_diffrence_L_infty}
				\norm{(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t}) f}_{L^{\infty}}
				\lesssim_{c} \abs{\Gamma_1 - \Gamma_2} \norm{f}_{L^{\infty}}.
			\end{equation}

			Indeed,
			we have

			\begin{equation*}
				(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t}) f(x) = \int_{\mathbb{R}^{d_1}} \left(p_{\Gamma_1 t}(y) - p_{\Gamma_2 t}(y)\right) f(x - y) \, \mathrm{d} y.
			\end{equation*}

			By \cite[Prop.~2.7]{dareiotis_gerenscer_le_23_euler},

			\begin{equation}\label{eq:heat_kernel_difference}
				\abs{p_{\Gamma_1 t}(y) - p_{\Gamma_2 t}(y)} \lesssim_c
				\abs{\Gamma_1 - \Gamma_2} (p_{\Gamma_1 t/2}(y) + p_{\Gamma_2 t/2}(y)),
			\end{equation}

			which yields the estimate \eqref{eq:semigroup_diffrence_L_infty}.

			Next we prove the estimate \eqref{eq:semigroup_difference} for $\alpha = \beta \notin \mathbb{N}$.
			The proof uses the characterization of Besov spaces by Littlewood--Paley blocks \cite{bahouri_chemin_danchin_11_fourier}.
			The case for $\alpha = \beta = 0$ is proved by \eqref{eq:semigroup_diffrence_L_infty}.
			Let $\{\Delta_j\}_{j=-1}^{\infty}$ be Littlewood--Paley blocks.
			Since $\Delta_j$ and $\mathcal{P}_{\Gamma_i t}$ commute, the estimate \eqref{eq:semigroup_diffrence_L_infty} yields

			\begin{equation*}
				\norm{\Delta_j (\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t})f}_{L^{\infty}}
				\lesssim_c \abs{\Gamma_1 - \Gamma_2} \norm{\Delta_j f}_{L^{\infty}}.
			\end{equation*}

			Therefore,

			\begin{equation*}
				\norm{(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t}) f}_{\mathcal{C}^{\beta}_x}
				\lesssim_{c} \abs{\Gamma_1 - \Gamma_2} 
				\norm{f}_{\mathcal{C}^{\beta}_x}.
			\end{equation*}


			Next we prove the estimate \eqref{eq:semigroup_difference} for $\alpha = \beta \in \mathbb{N}$.
			Since we only need the case $\alpha = \beta =1$, we only prove that case. We have

			\begin{equation*}
				\abs{(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t})f(x) - (\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t})f(y)} 
				\leq \int_{\mathbb{R}^{d_1}} \abs{p_{\Gamma_1 t}(z) - p_{\Gamma_2 t}(z)} \abs{f(x - z) - f(y - z)} \, \mathrm{d} z.
			\end{equation*}

			By \eqref{eq:heat_kernel_difference},

			\begin{multline*}
				\abs{(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t})f(x) - (\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t})f(y)} \\ 
				\lesssim_c \abs{\Gamma_1 - \Gamma_2} \int_{\mathbb{R}^{d_1}} \abs{p_{\Gamma_1 t/2}(z) + p_{\Gamma_2 t/2}(z)} \abs{f(x - z) - f(y - z)} \, \mathrm{d} z, 
			\end{multline*}

			which is then bounded by  
			$2 \abs{\Gamma_1 - \Gamma_2} \norm{f}_{C^1} \abs{x - y}$.

			Finally, we prove the general case. Since

			\begin{equation*}
				\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t} = (\mathcal{P}_{\Gamma_1 t/2} - \mathcal{P}_{\Gamma_2 t/2}) \mathcal{P}_{\Gamma_1 t /2}
				+ \mathcal{P}_{\Gamma_2 t / 2} (\mathcal{P}_{\Gamma_1 t/2} - \mathcal{P}_{\Gamma_2 t/2}),
			\end{equation*}

			we have

			\begin{equation*}
				\norm{(\mathcal{P}_{\Gamma_1 t} - \mathcal{P}_{\Gamma_2 t}) f}_{\mathcal{C}^{\beta}_x} 
				\leq \norm{ (\mathcal{P}_{\Gamma_1 t/2} - \mathcal{P}_{\Gamma_2 t/2}) \mathcal{P}_{\Gamma_1 t /2} f}_{\mathcal{C}^{\beta}_x}
				+ \norm{ \mathcal{P}_{\Gamma_2 t / 2} (\mathcal{P}_{\Gamma_1 t/2} - \mathcal{P}_{\Gamma_2 t/2}) f}_{\mathcal{C}^{\beta}_x}.
			\end{equation*}

			As for the first term, the estimate \eqref{eq:semigroup_difference} with $\alpha = \beta$ and Lem.~\ref{lem:semigroup_regularisation}
			imply

			\begin{equation*}
				\norm{ (\mathcal{P}_{\Gamma_1 t/2} - \mathcal{P}_{\Gamma_2 t/2}) \mathcal{P}_{\Gamma_1 t /2} f}_{\mathcal{C}^{\beta}_x}
				\lesssim_c \abs{\Gamma_1 - \Gamma_2} \norm{ \mathcal{P}_{\Gamma_1 t /2} f}_{\mathcal{C}^{\beta}_x} 
				\lesssim_{c, \alpha, \beta} \abs{\Gamma_1 - \Gamma_2} (t \wedge 1)^{-\frac{\beta - \alpha}{2}} \norm{f}_{\mathcal{C}_x^{\alpha}}.
			\end{equation*}

			The estimate of the second term is similar.

For notational concision, we write $Y^s \vcentcolon = Y^{H, s}$.
			Since $(s, \infty) \ni t \mapsto K_H(t, r)$ is smooth for any $r \in [0, s]$, the process $(s,\infty) \ni t\mapsto Y^s_t$ is smooth, hence we can legitimately take its derivative in this region, which is all that the lemma requires. The estimate on $Y^{s}_{u, t}$ readily follows from that on $\dot{Y}^s_t$, through the 
			identity $Y^{s}_{u, t} = \int_u^t \dot{Y}^s_r \, \mathrm{d} r$.
			Therefore, we focus on the estimate on $\dot{Y}^s_t$.

			To this end, we use the Mandelbrot--Van Ness representation \cite{mandelbrot68}: 

			\begin{equation*}
				B^H_t = \int_{-\infty}^t \bar{K}_H(t, r) \, \mathrm{d} \bar{W}_r, \quad \tilde{K}_H(t, r) 
				\vcentcolon = \bar{c}_H ((t-r)^{H-\frac{1}{2}} - (-r)_+^{H-\frac{1}{2}}),
			\end{equation*}

			where $\bar{W}$ is a two-sided Brownian motion and $\bar{c}_H$ is a suitably chosen constant. We set 

			\begin{equation*}
				\mathcal{F}_t \vcentcolon = \sigma(B^H_r : r \in [0, t]), \quad \bar{\mathcal{F}}_t \vcentcolon = \sigma(\bar{W}_r : r \in (-\infty, t]),
			\end{equation*}

			and $\bar{Y}^s_t \vcentcolon = \mathbb{E}[B^H_t \vert  \bar{\mathcal{F}}_s]$. 
			Since $\mathcal{F}_t \subseteq \bar{\mathcal{F}}_t$ and $Y^s_t = \mathbb{E}[\bar{Y}^s_t \vert \bar{\mathcal{F}}_s]$, we have
			$\dot{Y}^s_t = \mathbb{E}[\dot{\bar{Y}}^s_t \vert \bar{\mathcal{F}}_s]$.
			Therefore, it suffices to estimate $\dot{\bar{Y}}^s_t$, and we observe that 

			\begin{equation*}
				\norm{\dot{\bar{Y}}^s_t}_{L^p_{\omega}}
				\lesssim_p \norm{\dot{\bar{Y}}^s_t}_{L^2_{\omega}}
				= \Big( \int_{-\infty}^s \abs{\partial_t \bar{K}_H(t, r)}^2 \, \mathrm{d} r \Big)^{\frac{1}{2}}
				\lesssim (t-s)^{H-1}. \qedhere
			\end{equation*}

Since $\mathbb{B}^{H, s}$ satisfies Chen's relation \eqref{eq:chen_relation} and $Y^{H, s}$ is smooth, it is easy to see that 
			$\tilde{\mathbb{B}}^{H, s}$ also satisfies Chen's relation. 
			To see the regularity estimate, by Kolmogorov's continuity criterion for rough paths \cite[Thm.~3.1]{FH20}, it suffices to show that 

			\begin{align}\label{eq:tilde_bold_B_bound}
				\norm{\tilde{\mathbb{B}}^{H, s}_{u, t}}_{L^p_{\omega}} 
				\lesssim_p (t-u)^{2 H}.
			\end{align}

			But, since we already know the estimates on $\mathbb{B}^{H, s}$ and on $\dot{Y}^{H, s}$ from Lem.~\ref{lem:Y_dot}, the bound \eqref{eq:tilde_bold_B_bound} easily follows. 

			To see that $(\tilde{B}^{H, s}, \tilde{\mathbb{B}}^{H, s})$ is a geometric rough path of order $\alpha$, by \cite[Prop.~2.8]{FH20} it suffices to show that 
			the rough path is weakly geometric, i.e. 

			\begin{align*}
				\tilde{\mathbb{B}}^{H, s, i, j}_{u, t} + \tilde{\mathbb{B}}^{H, s, j, i}_{u, t} =  \tilde{B}^{H, s, i}_{u, t} \tilde{B}^{H, s, j}_{u, t}, 
			\end{align*}

			but this algebraic identity is easy to verify, since $(B^{H}, \mathbb{B}^H)$ is geometric.

\label{lem:g_times_iterated_integral}
			Let $H \in (1/3, 1/2]$ and $0 \leq s \leq u < t$, and we define $\tilde{B}^{H, s}$ by \eqref{eq:def_tilde_B} and $\tilde{\mathbb{B}}^{H, s}$ by \eqref{eq:tilde_bold_B}.
			Let $g \colon \mathbb{R}^{d_2} \to \mathbb{R}$ be such that $g(\tilde{B}^{H, s}_u) \in L^2_{\omega}$. 
			Then we have 

			\begin{align*}
				\mathbb{E}\left[g(\tilde{B}_u^{H, s}) \tilde{\mathbb{B}}^{H, s, i, j}_{u, t} \right] 
				= \frac{1}{2} \mathbb{E}[g(\tilde{B}^{H, s}_u) \tilde{B}_{u, t}^{H, s, i} \tilde{B}_{u, t}^{H, s, j}].
			\end{align*}

\label{lem:rough_vs_stratonovich}
			Let $H \in (1/3, 1/2]$ and $\tau \geq 0$, and we define $\tilde{B}^{H, \tau}$ by \eqref{eq:def_tilde_B} 
			and define $\tilde{\mathbb{B}}^{H, \tau}$ by \eqref{eq:tilde_bold_B}.
			Let $g \colon \mathbb{R}^{d_2} \to \mathbb{R}$ be a bounded measurable function. 


			We set 

			\begin{align*}
				A_{s, t}^1 \vcentcolon = g(\tilde{B}^{H, \tau}_s) \tilde{B}^{H, \tau, i}_{s, t} \tilde{B}^{H, \tau, j}_{s, t}, 
				\quad A_{s, t}^2 \vcentcolon = g(\tilde{B}^{H, \tau}_s) \tilde{\mathbb{B}}^{H, \tau, i, j}_{s, t}.
			\end{align*}

			We write $(\mathcal{F}_t)_{t \geq 0}$ for the filtration generated by $(B^H_t)_{t \geq 0}$.
			Then, for $p \in [2, \infty)$ and $\tau \leq v < s < t$ with $t-s \leq s-v$, we have 

			\begin{align*}
				\norm{\mathbb{E}[A^1_{s,t} - 2 A^2_{s, t} \vert \mathcal{F}_v]}_{L^p_{\omega}}
				\lesssim_{p} \norm{g}_{L^{\infty}_x} \Big( \frac{t-s}{s-v} \Big)^{1 - H} (t-s)^{2 H}.
			\end{align*}

For simplicity, we drop scripts on $H$. Recalling the Volterra representation \eqref{eq:fbm_volterra}, we set 

			\begin{align}\label{eq:Y_tau_v}
				Y^{\tau, v}_t \vcentcolon = \int_{\tau}^v K_H(t, r) \, \mathrm{d} W_r = Y^{v}_t - Y^{\tau}_t. 
			\end{align}

			Note that $Y^{\tau, v} = \mathbb{E}[\tilde{B}^{\tau} \vert \mathcal{F}_v]$ 
			and 
			$\tilde{B}^{\tau} - Y^{\tau, v} = \tilde{B}^{v}$
			is independent of $\mathcal{F}_v$.
			We have 

			\begin{align*}
				A^1_{s, t} 
				= g(Y_s^{\tau, v} + \tilde{B}^v_s) [Y_{s, t}^{\tau, v, i} Y_{s, t}^{\tau, v, i} 
				+ Y_{s, t}^{\tau, v, i} \tilde{B}^{v, j}_{s, t} + \tilde{B}^{v, i}_{s, t} Y_{s, t}^{\tau, v, j} 
				+ \tilde{B}^{v, i}_{s, t} \tilde{B}^{v, j}_{s, t}].
			\end{align*}

			To estimate the first three terms, observe by Lem.~\ref{lem:Y_dot} that 

			\begin{align}\label{eq:Y_tau_v_estimate}
				\norm{Y_{s, t}^{\tau, v}}_{L^p_{\omega}} \leq  \norm{Y^{v}_{s, t}}_{L^p_{\omega}}
				\lesssim_{p} (s-v)^{H - 1} (t-s),   
			\end{align}

			and by \eqref{eq:rho_lower_bd} that $\norm{\tilde{B}^v_{s, t}}_{L^p_{\omega}} \lesssim_p (t-s)^H$.
			Hence, we obtain 

			\begin{align*}
				\norm{A^1_{s, t} - g(Y_s^{\tau, v} + \tilde{B}^v_s) \tilde{B}^{v, i}_{s, t} \tilde{B}^{v, j}_{s, t}}_{L^p_{\omega}} 
				\lesssim_{p} \norm{g}_{L^{\infty}_x} \Big( \frac{t-s}{s-v} \Big)^{1-H} (t-s)^{2H}.
			\end{align*}

			Similarly, $A^2_{s,t}$ equals to 

			\begin{equation*}
				g(Y_s^{\tau, v} + \tilde{B}_s^v) 
				\Big[ \int_s^t Y_{s, r}^{\tau, v, i} \dot{Y}_r^{\tau, v, j} \, \mathrm{d} r + 
				\int_s^t Y_{s, r}^{\tau, v, i} \, \mathrm{d} \tilde{B}^{v, j}_r 
				+ \int_s^t \tilde{B}^{ v, i}_{s, r} \dot{Y}_r^{\tau, v, j} \, \mathrm{d} r
				+ \tilde{\mathbb{B}}^{v, i, j}_{s, t}
				\Big]
			\end{equation*}

			and 

			\begin{align*}
				\norm[\Big]{A^2_{s, t} - g(Y^{\tau, v}_s + \tilde{B}_s^v)  \tilde{\mathbb{B}}^{v, i, j}_{s, t}}_{L^p_{\omega}} 
				\lesssim_p \norm{g}_{L^{\infty}_x} \Big( \frac{t-s}{s-v} \Big)^{1-H} (t-s)^{2 H}.
			\end{align*}

			To complete the proof, it remains to observe

			\begin{align}\label{eq:tilde_B_iterated_integral}
				\mathbb{E}[g(Y_s + \tilde{B}_s)  \tilde{\mathbb{B}}^{v, i, j}_{s, t}  \vert \mathcal{F}_v ]
				= \frac{1}{2} \mathbb{E}[g(Y_s + \tilde{B}_s) \tilde{B}^i_{s, t} \tilde{B}_{s, t}^j 
				\vert \mathcal{F}_v],
			\end{align}

			which follows from Lem.~\ref{lem:g_times_iterated_integral}.

\label{lem:rough_vs_strat_2}

			Let $H \in (1/3, 1)$ and $\tau \geq 0$, and we define $\tilde{B}^{H, \tau}$ by \eqref{eq:def_tilde_B}. 

			Let $g \in C^2(\mathbb{R}^{d_2})$. We then have 

			\begin{align*}
				\int_s^t g(\tilde{B}^{H, \tau}_r) \, \mathrm{d} \tilde{B}^{H, \tau}_r = 
				\lim_{\substack{\pi \text{ is a partition of }[s, t], \\ \abs{\pi} \to 0 }} 
				\sum_{[s', t'] \in \pi} \frac{g(\tilde{B}^{H, \tau}_{s'}) + g(\tilde{B}^{H, \tau}_{t'})}{2} \tilde{B}^{H, \tau}_{s', t'},
			\end{align*} 

			where the convergence is in $L^p_{\omega}$ for any $p \in [1, \infty)$.

For simplicity, we drop scripts on $H$.
			When $H > 1/2$, the claim follows from the remainder estimate of the Young integral \eqref{eq:young_fund_est}. 
			Hence, we assume that $H \leq 1/2$.

			We set 

			\begin{equation*}
				A^1_{s, t} \vcentcolon = g(\tilde{B}^{\tau}_s) \tilde{B}^{\tau}_{s, t} 
				+ \nabla g(\tilde{B}^{\tau}_s) \tilde{\mathbb{B}}^{\tau}_{s, t},
				\quad 
				A^2_{s, t} \vcentcolon = \frac{g(\tilde{B}^{\tau}_s) + g(\tilde{B}^{\tau}_t)}{2} \tilde{B}^{\tau}_{s, t}.
			\end{equation*}

			The integral $\int_s^t g(\tilde{B}^{\tau}_r) \, \mathrm{d} \tilde{B}^{\tau}_r$ is understood as rough integral: 

			\begin{align}\label{eq:g_integral_by_A_1}
				\int_s^t g(\tilde{B}^{\tau}_r) \, \mathrm{d} \tilde{B}^{\tau}_r
				= \lim_{\substack{\pi \text{ is a partition of } [s, t], \\ \abs{\pi} \to 0}} \sum_{[s', t'] \in \pi} A^1_{s', t'}\quad \text{in } L^p_{\omega}.
			\end{align}


			The proof relies on the uniqueness part of the deterministic and stochastic sewing lemma (Rem.~\ref{rem:sewing_uniq}). 
			We have 

			\begin{align}
				A^2_{s, t} - A^1_{s, t} 
				&= \frac{g(\tilde{B}^{\tau}_t) - g(\tilde{B}^{\tau}_s)}{2} 
				\tilde{B}^{\tau}_{s, t} 
				- \nabla g(\tilde{B}^{\tau}_s) \tilde{\mathbb{B}}^{\tau}_{s, t} \notag\\
				&= \frac{1}{2} \nabla g(\tilde{B}^{\tau}_s) \tilde{B}^{\tau}_{s,t} \otimes \tilde{B}^{\tau}_{s, t} 
				- \nabla g(\tilde{B}^{\tau}_s) \tilde{\mathbb{B}}^{\tau}_{s, t}
				+ R_{s, t}, \label{eq:A^2_minus_A^1_g}
			\end{align}

			where 

			$\abs{R_{s, t}} \lesssim_{\norm{g}_{C^2_x}} \abs{\tilde{B}^{\tau}_{s, t}}^3$.

			Setting $A^3_{s, t} \vcentcolon = A^2_{s, t} - A^1_{s,t} - R_{s, t}$, we therefore see that 

			\begin{align}\label{eq:A_1_A_2_A_3}
				\lim_{\abs{\pi} \to 0} \sum_{[s', t'] \in \pi} (A^2_{s', t'} - A^1_{s', t'}) = 
				\lim_{\abs{\pi} \to 0} \sum_{[s', t'] \in \pi}  A^3_{s', t'}  \quad \text{in } L^p_{\omega}.
			\end{align}

			To estimate the right-hand side, we will apply the uniqueness part of Lem.~\ref{lem:ssl}.
			Using \eqref{eq:A^2_minus_A^1_g} and Lem.~\ref{lem:rough_vs_stratonovich}, we obtain 

			\begin{align*}
				\norm{A^3_{s,t}}_{L^p_{\omega}} \lesssim_{p, \norm{g}_{C^1_x}} (t-s)^{2H},
				\quad 
				\norm{\mathbb{E}[A^3_{s, t} \vert \mathcal{F}_v]}_{L^p_{\omega}} 
				\lesssim_{p, \norm{g}_{C^1_x}}  \Big( \frac{t-s}{s-v} \Big)^{1-H}(t-s)^{2H}.
			\end{align*}


			Hence, applying the uniqueness part of Lem.~\ref{lem:ssl}, the claim is proven in view of \eqref{eq:g_integral_by_A_1} 
			and \eqref{eq:A_1_A_2_A_3}.

\label{lem:K_derivative_K}
			Let $H \in (1/3, 1/2)$ and we define $K_H$ by \eqref{eq:K_H_less_12}. 
			Then, for $0 \leq v < s \leq t$, we have 

			\begin{align*}
				\abs[\Big]{\int_0^v K_H(s, r) \partial_t K_H(t, r) \, \mathrm{d} r } \lesssim (s-v)^{2H - 1}.
			\end{align*}

Recalling \eqref{eq:K_H_less_12} and observing 

			\begin{equation*}
				\frac{\partial}{\partial t} K_H(t, s) = c_H \Big( H - \frac{1}{2} \Big) \Big( \frac{t}{s} \Big)^{H- \frac{1}{2}} 
				(t-s)^{H-\frac{3}{2}},
			\end{equation*}

			it suffices to prove 

			\begin{gather}\label{eq:derivative_K_est_1}
				\int_0^v \Big( \frac{s}{r} \Big)^{H-\frac{1}{2}} (s-r)^{H-\frac{1}{2}} \Big( \frac{t}{r} \Big)^{H-\frac{1}{2}} (t-r)^{H-\frac{3}{2}} \, \mathrm{d} r
				\lesssim (s-v)^{2H - 1}, \\
				\int_0^v \Big( \frac{t}{r} \Big)^{H - \frac{1}{2}} (t-r)^{H - \frac{3}{2}} r^{\frac{1}{2} - H} 
				\Big( \int_r^s u^{H - \frac{3}{2}} (u-r)^{H - \frac{1}{2}} \, \mathrm{d} u \Big) \, \mathrm{d} r
				\lesssim (s-v)^{2H - 1}. \label{eq:derivative_K_est_2}
			\end{gather}

			The estimate \eqref{eq:derivative_K_est_1} is straightforward. Indeed, noting that $r/t \leq 1$, $r/s \leq 1$ and $s-r \leq t-r$, the 
			left-hand side is bounded by 

			$(s-v)^{2H - 1}$ up to constant.

			To prove \eqref{eq:derivative_K_est_2}, using again $r/t \leq 1$ and also for $r \in [0, v]$

			\begin{align*}
				(t-r)^{H - \frac{3}{2}} = (t-r)^{2H - 1} (t-r)^{-H-\frac{1}{2}} \leq (s-v)^{2H - 1} (t-r)^{-H-\frac{1}{2}},
			\end{align*}

			the left-hand side of \eqref{eq:derivative_K_est_2} is bounded by $(s-v)^{2H-1} I$, where

			\begin{align*}
				I \vcentcolon = \int_0^v (t-r)^{-H-\frac{1}{2}} r^{\frac{1}{2} - H} \Big( \int_r^t u^{H-\frac{3}{2}} (u-r)^{H-\frac{1}{2}} \, \mathrm{d} u \Big)  \, \mathrm{d} r.
			\end{align*}

			Therefore, it suffices to show $I \lesssim 1$.

			Applying the bound 

			\begin{align*}
				u^{H - \frac{3}{2}} = u^{-1} u^{H - \frac{1}{2}} \leq r^{-1} (u-r)^{H - \frac{1}{2}}, \quad u \in [r, t],
			\end{align*}

			we get 

			\begin{align*}
				I &\leq \int_0^v (t-r)^{-H-\frac{1}{2}} r^{\frac{1}{2} - H} r^{-1} \Big( \int_r^t  (u-r)^{2 H-1} \, \mathrm{d} u \Big)  \, \mathrm{d} r \lesssim \int_0^v (t-r)^{H - \frac{1}{2}} r^{-\frac{1}{2} - H} \, \mathrm{d} r \\
				&\leq \int_0^t (t-r)^{H - \frac{1}{2}} r^{-\frac{1}{2} - H} \, \mathrm{d} r 
				= \int_0^1 (1 - s)^{H - \frac{1}{2}} s^{-\frac{1}{2} - H} \, \mathrm{d} s. \qedhere 
			\end{align*}

\label{lem:rho_and_tilde_B}

			Let $H \in (1/3, 1/2]$, and we define $\tilde{B}^{H, v}$ by \eqref{eq:def_tilde_B} and $\rho_H(v, t)$ by \eqref{eq:def_rho}. 
			Let $v < s < t$. 

			\begin{enumerate}
				\item For $i \in \{1, 2, \ldots, d_2\}$, we have 

				\begin{align*}
					\left|\mathbb{E}\left[\tilde{B}_s^{H, v, i} \tilde{B}_{s, t}^{H, v, i}\right]\right| + \left|\mathbb{E}\left[\tilde{B}_t^{H, v, i} \tilde{B}_{s, t}^{H, v, i}\right]\right| \lesssim (t-s)^{2H} + (s-v)^{2H - 1} (t-s).
				\end{align*}

				\item We have $\abs{\rho_H^2(v, t) - \rho_H^2(v, s)} \lesssim (t-s)^{2H} + (s-v)^{2H - 1} (t-s) $.

			\end{enumerate}

When $H = 1/2$ the claim is trivial, so we suppose that $H < 1/2$.

			\textbf{Proof of 1.} By \eqref{eq:rho_lower_bd}, we have 

			$\mathbb{E}[\abs{B^{H, v}_{s, t}}^2] \lesssim (t-s)^{2H}$.

			Hence, it suffices to estimate $\mathbb{E}[\tilde{B}^{H, v, i}_s \tilde{B}^{H, v, i}_{s, t}]$.
			Recall $Y^{H, v}$ from \eqref{eq:def_Y}. Since $Y^{H, v}$ and $\tilde{B}^{H, v}$ are independent and $B^H = Y^{H, v} + \tilde{B}^{H, v}$, 
			we have 

			\begin{align*}
				\mathbb{E}\left[B_s^{H, i} B_{s, t}^{H, i}\right] = \mathbb{E}\left[Y_s^{H, v, i} Y_{s, t}^{H, v, i}\right] 
				+ \mathbb{E}\left[\tilde{B}_s^{H, v, i} \tilde{B}_{s, t}^{H, v, i}\right].
			\end{align*}  

			As for $B^H$, the computation is explicit, and it is easy to see that the left-hand side is bounded by $(t-s)^{2H}$ up to constant.


			Therefore, it suffices to prove $\abs{\mathbb{E}[Y_s^{H, v, i} Y_{s, t}^{H, v, i}]} \lesssim (s-v)^{2H - 1} (t-s)$. 
			However, this follows from the bound 

			\begin{align*}
				\left|\mathbb{E}\left[Y^{H, v, i}_s \dot{Y}^{H, v, i}_t\right]\right| \lesssim (s-v)^{2H - 1},
			\end{align*}

			which in turn follows from Lem.~\ref{lem:K_derivative_K}.

			\textbf{Proof of 2.} We have 

			\begin{align*}
				\rho^2_H(v, t) - \rho^2_H(v, s) +  \mathbb{E}\Big[\Big(Y^{H, v, i}_t\Big)^2\Big] - \mathbb{E}\Big[\Big(Y^{H, v, i}_s\Big)^2\Big] 
				= \mathbb{E}\Big[\Big(B_t^{H, i}\Big)^2\Big] - \mathbb{E}\Big[\Big(B_s^{H, i}\Big)^2\Big].  
			\end{align*}

			Since 

			\begin{align*}
				0 \leq \mathbb{E}\Big[\Big(B_t^{H, i}\Big)^2\Big] - \mathbb{E}\Big[\Big(B_s^{H, i}\Big)^2\Big]
				= t^{2H} - s^{2H} \leq (t-s)^{2H},
			\end{align*}

			it suffices to prove $\abs{\mathbb{E}[(Y^{H, v, i}_t)^2] - \mathbb{E}[(Y^{H, v, i}_s)^2]} 
			\lesssim  (s-v)^{2H - 1} (t-s)$. However, this follows from the bound 

			\begin{align*}
				\abs[\Big]{\frac{\mathrm{d}}{\mathrm{d} t} \mathbb{E}\Big[\Big(Y^{H, v, i}_t\Big)^2\Big]} = 2 \Big|\mathbb{E}\Big[Y^{H, v, i}_t \dot{Y}^{H, v, i}_t\Big]\Big| \lesssim (t-v)^{2H - 1},
			\end{align*}

			which follows from Lem.~\ref{lem:K_derivative_K}.

\label{lem:integral_stratonovich}

			Let $H \in (1/3, 1/2]$ and $B^H$ be an $(\mathcal{F}_t)$-fBm. 
			We fix a $\tau \in [0, T]$ and define  $\tilde{B}^{H, \tau}$ by  \eqref{eq:def_tilde_B}.
			Let $\xi$ be an $\mathcal{F}_{\tau}$-measurable random variable valued in some measurable space $E$.
			Suppose that $F \colon E \times \mathbb{R}^{d_2} \to \mathbb{R}$ satisfies 

			\begin{align*}
				\abs{F(x, y_1) - F(x, y_2)} \leq M(x) 

				\abs{y_1 - y_2}^{\gamma}
			\end{align*}  

			for all $x \in E$ and $y_1, y_2 \in \mathbb{R}^{d_2}$,
			with $\gamma \in (\frac{1}{2H} - 1, 1]$. 
			We set 

			\begin{align*}
				A_{s, t} \vcentcolon = (F(\xi, B^H_s) + F(\xi, B^H_t)) \tilde{B}_{s, t}^{H, \tau, i}.
			\end{align*}

			For $\tau \leq v < s < u < t$ with $t-s \leq s-v$, we then have 

			\begin{align}
				\label{eq:delta_A_stratonovich}
				\norm{\delta A_{s, u, t}}_{L^p_{\omega}} 
				&\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} (t-s)^{(1 + \gamma) H},\\
				\label{eq:delta_A_conditional_stratonovich}
				\norm{\mathbb{E}[\delta A_{s, u, t} \vert \mathcal{F}_v]}_{L^p_{\omega}} 
				&\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} \Big( \frac{t-s}{s-v} \Big)^{(3-\gamma)H} 
				(t-s)^{(1 + \gamma) H}.
			\end{align}

We essentially repeat the argument of \cite[Prop.~3.5]{matsuda22}.
			For simplicity, we drop scripts on $H$.
			We first consider the estimate \eqref{eq:delta_A_stratonovich}. 
			We compute 

			\begin{align*}
				\delta A_{s, u, t} 
				= F(\xi, B)_{u, t} \tilde{B}^{\tau, i}_{s, u} 
				- F(\xi, B)_{s, u} \tilde{B}^{\tau, i}_{u, t},
			\end{align*}

			and 

			\begin{align*}
				\abs{\delta A_{s, u, t}} 
				\leq M(\xi) \big[\abs{B_{u, t}}^{\gamma} \abs{\tilde{B}^{\tau}_{s, u}}
				+ \abs{B_{s, u}}^{\gamma} \abs{\tilde{B}^{\tau}_{u, t}} \big].
			\end{align*}

			In view of \eqref{eq:rho_lower_bd}, it is easy to see the estimate \eqref{eq:delta_A_stratonovich}.

			We turn to the estimate \eqref{eq:delta_A_conditional_stratonovich}.
			We recall $Y^{v}$ from \eqref{eq:def_Y} and $Y^{\tau, v}$ from \eqref{eq:Y_tau_v}, and we recall the decomposition 
			$B = Y^v + \tilde{B}^v$ and $\tilde{B}^{\tau} = Y^{\tau, v} + \tilde{B}^v$, 
			where $Y^v$ and $Y^{\tau, v}$ are measurable with respect to $\mathcal{F}_v$ and $\tilde{B}^v$ is independent of $\mathcal{F}_v$.
			We set 

			\begin{equation*}
				a_0(s) \vcentcolon = \mathbb{E}[F(x, y_s + \tilde{B}^{v}_s)] \vert_{x = \xi, y = Y^v}, \quad
				a_i(s) \vcentcolon =  \rho^{-2}(v, s)
				\mathbb{E}[F(x, y_s + \tilde{B}^v_s) \tilde{B}^{v, i}_s] \vert_{x = \xi, y = Y^v}
			\end{equation*}

			with $\rho = \rho_H$ defined by \eqref{eq:def_rho}.
			As in \cite[Prop.~3.5]{matsuda22}, especially \cite[Eq.~(3.8) and (3.11)]{matsuda22}, we have 

			$\mathbb{E}[\delta A_{s, u, t} \vert \mathcal{F}_v]
			= D^0_{s, u, t} + D^i_{s, u, t}$,

			where

			\begin{align*}
				D^0_{s, u, t} &\vcentcolon = (a_0(t) - a_0(u))  Y_{s, u}^{\tau, v, i} + (a_0(s) - a_0(u))  Y_{u, t}^{\tau, v, i}, \\
				D^i_{s, u, t} &\vcentcolon = (a_i(t) - a_i(u)) \mathbb{E}[\tilde{B}_t^{v, i} \tilde{B}_{s, t}^{v, i}]
				+ (a_i(s) - a_i(u)) \mathbb{E}[\tilde{B}_s^{v, i} \tilde{B}_{s, t}^{v, i}] \\
				&\phantom{\vcentcolon =} -(a_i(s) - a_i(u)) \mathbb{E}[\tilde{B}_s^{v, i} \tilde{B}_{s, u}^{v, i}]
				-(a_i(t) - a_i(u)) \mathbb{E}[\tilde{B}_t^{v, i} \tilde{B}_{u, t}^{v, i}].
			\end{align*}


			The estimate as in \cite[Eq.~(3.9)]{matsuda22} gives

			\begin{equation*}
				\abs{D^0_{s, u, t}} 
				\lesssim_{\gamma} M(\xi) \big[ \rho^{(\gamma-1)}(v, s) \abs{Y^{\tau, v}_{s,u}}\abs{Y^{\tau, v}_{u,t}} 
				+ \rho^{\gamma -1}(v, s)[\rho(v, t) - \rho(v, s)] (\abs{Y_{s, u}^{\tau, v}} + \abs{Y^{\tau, v}_{u, t}}) \big].
			\end{equation*}

			To estimate $\rho(v, t) - \rho(v, s)$, we observe that 

			\begin{align*}
				\rho(v, t) - \rho(v, s) &= (\rho(v, t) + \rho(v, s))^{-1} [\rho^2(v, t) - \rho^2(v, s)] \\
				&\leq 2 \rho^{-1}(v, s) [\rho^2(v, t) - \rho^2(v, s)] \\
				&\lesssim \rho^{-1}(v, s) [(t-s)^{2H} + (s-v)^{2H - 1} (t-s)],
			\end{align*}

			where the last inequality follows from Lem.~\ref{lem:rho_and_tilde_B}.
			Using the bound on $\rho$ from \eqref{eq:rho_lower_bd} and that on $Y^{\tau, v}$ from \eqref{eq:Y_tau_v_estimate}, 
			we obtain

			\begin{equation*}
				\norm{D^0_{s, u, t}}_{L^p_{\omega}} 
				\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} [(s - v)^{(\gamma + 1)H - 2} (t - s)^2
				+ (s - v)^{(\gamma - 1) H - 1} (t - s)^{1 + 2H}]. 
			\end{equation*}

			Since 

			$(s-v)^{(\gamma + 1)H -2} (t-s)^2 \leq (s-v)^{(\gamma - 1)H - 1} (t-s)^{1 + 2H}$,

			we have 

			\begin{align*}
				\norm{D^0_{s, u, t}}_{L^p_{\omega}} 
				\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} 
				(s - v)^{(\gamma - 1) H - 1} (t - s)^{1 + 2H}. 
			\end{align*}


			To estimate $D^i_{s, u, t}$, as in \cite{matsuda22} (see the two estimates before (3.12) therein), we have 

			\begin{align*}
				\abs{a_i(t) - a_i(u)} \lesssim_{\gamma} M(\xi) \rho^{\gamma-1}(v, u) (\abs{Y^v_{u, t}} + \rho(v, t) - \rho(v, u)).  
			\end{align*}

			Therefore, estimating $Y^v$ and $\rho(v, t) - \rho(v, u)$ as before, we obtain 

			\begin{align*}
				\norm{a_i(t) - a_i(u)}_{L^p_{\omega}} 
				&\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} 
				[\rho^{\gamma-2}(v, u) (u-v)^{H - 1} (t-u) + \rho^{\gamma-3}(v, u) (t-u)^{2H} ] \\
				&\lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}} (u-v)^{(\gamma - 3)H} (t-u)^{2H}.
			\end{align*}

			Combining the estimate of $\mathbb{E}[\tilde{B}^{v, i}_u \tilde{B}^{v, i}_{u, t}]$ from Lem.~\ref{lem:rho_and_tilde_B}-(i), we obtain

			\begin{equation*}
				\norm{D^i_{s, u, t}}_{L^p_{\omega}} \lesssim_{p, \gamma} \norm{M(\xi)}_{L^{2p}_{\omega}}
				(s - v)^{(\gamma - 3) H} (t - s)^{4H}.
			\end{equation*}

			Now the estimate \eqref{eq:delta_A_conditional_stratonovich} is proven.
